import { TestBed } from '@angular/core/testing';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function tmdbMovie(id: number, title: string): TmdbMovie {
  return { id, title, release_date: '2024-01-01', poster_path: null, overview: 'synopsis' };
}

function seededStore(): WatchlistStore {
  const store = new WatchlistStore();
  store.add(tmdbMovie(1, 'Watched A'));
  store.add(tmdbMovie(2, 'Unwatched B'));
  store.add(tmdbMovie(3, 'Watched C'));
  store.add(tmdbMovie(4, 'Unwatched D'));
  store.toggleWatched(1);
  store.toggleWatched(3);
  return store;
}

describe('watchlist (acceptance)', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('shows unwatched movies before watched ones, preserving relative order', () => {
    const store = seededStore();
    TestBed.configureTestingModule({ providers: [{ provide: WatchlistStore, useValue: store }] });

    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;

    const ids = component.movies().map((movie) => movie.id);
    expect(ids).toEqual([2, 4, 1, 3]);
    expect(component.watchedCount()).toBe(2);
  });

  it('keeps the sorted list rendering in the template', () => {
    const store = seededStore();
    TestBed.configureTestingModule({ providers: [{ provide: WatchlistStore, useValue: store }] });

    const fixture = TestBed.createComponent(Watchlist);
    fixture.detectChanges();

    const component = fixture.componentInstance;
    const ids = component.movies().map((movie) => movie.id);
    expect(ids).toEqual([2, 4, 1, 3]);
    const unwatched = component.movies().filter((movie) => !movie.watched);
    const watched = component.movies().filter((movie) => movie.watched);
    expect(unwatched.length).toBe(2);
    expect(watched.length).toBe(2);
  });
});
```

