  store.add(tmdbMovie(2, 'Unwatched B'));
  store.add(tmdbMovie(3, 'Watched C'));
  store.add(tmdbMovie(4, 'Unwatched D'));
  store.toggleWatched(1);
  store.toggleWatched(3);

  return { store, fixture };
}

