function tmdbMovie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-05-01',
    poster_path: null,
    overview: 'A movie',
  };
}

function createWatchlist(): { store: WatchlistStore; fixture: ComponentFixture<Watchlist> } {
